// src/components/Button.jsx
import React from 'react';
import PropTypes from 'prop-types';

const Button = ({ children, onClick, variant = 'primary', className = '', ...props }) => {
  let baseStyles = "py-2 px-4 rounded-md font-semibold transition-colors duration-300 ease-in-out focus:outline-none focus:ring-2 focus:ring-offset-2";
  let variantStyles = "";

  switch (variant) {
    case 'primary':
      variantStyles = "bg-primary text-white hover:bg-primaryDark focus:ring-primary";
      break;
    case 'secondary':
      variantStyles = "bg-secondary text-white hover:bg-secondaryDark focus:ring-secondary";
      break;
    case 'dark':
      variantStyles = "bg-darkText text-white hover:bg-gray-800 focus:ring-darkText";
      break;
    case 'outline':
      variantStyles = "bg-transparent border-2 border-primary text-primary hover:bg-primary hover:text-white focus:ring-primary";
      break;
    case 'danger':
      variantStyles = "bg-red-600 text-white hover:bg-red-700 focus:ring-red-600";
      break;
    default:
      variantStyles = "bg-primary text-white hover:bg-primaryDark focus:ring-primary";
  }

  return (
    <button
      onClick={onClick}
      className={`${baseStyles} ${variantStyles} ${className}`}
      {...props}
    >
      {children}
    </button>
  );
};

Button.propTypes = {
  children: PropTypes.node.isRequired, // المحتوى داخل الزر (نص، أيقونات، إلخ)
  onClick: PropTypes.func,             // دالة يتم استدعاؤها عند النقر
  variant: PropTypes.oneOf(['primary', 'secondary', 'dark', 'outline', 'danger']), // نوع الزر
  className: PropTypes.string,         // كلاسات Tailwind إضافية
};

export default Button;
